const Suit = Object.freeze({ HEART: "heart", DIAMOND: "diamond", CLUB: "club", SPADE: "spade" });

class Card {
  constructor(rank, suit) {
    if (!Number.isInteger(rank) || rank < 1 || rank > 13) throw new RangeError("Invalid rank");
    if (!Object.values(Suit).includes(suit)) throw new RangeError("Invalid suit");
    this.rank = rank;
    this.suit = suit;
    this.available = true;
  }
  get value() { return this.rank; }
}
class BlackjackCard extends Card {
  get isAce() { return this.rank === 1; }
  get value() { return Math.min(this.rank, 10); }
}
class Hand {
  constructor(cards = []) { this.cards = [...cards]; }
  add(card) { this.cards.push(card); }
  score() { return this.cards.reduce((total, card) => total + card.value, 0); }
}
class BlackjackHand extends Hand {
  possibleScores() {
    let scores = new Set([0]);
    for (const card of this.cards) {
      const next = new Set();
      for (const total of scores) {
        next.add(total + card.value);
        if (card.isAce) next.add(total + 11);
      }
      scores = next;
    }
    return [...scores];
  }
  score() {
    const scores = this.possibleScores();
    const valid = scores.filter(score => score <= 21);
    return valid.length ? Math.max(...valid) : Math.min(...scores);
  }
}
class Deck {
  constructor(cards) { this.cards = [...cards]; this.dealIndex = 0; }
  get remaining() { return this.cards.length - this.dealIndex; }
  deal() {
    if (!this.remaining) return null;
    const card = this.cards[this.dealIndex++];
    card.available = false;
    return card;
  }
  // Shuffle only the undealt suffix. random() must return a value in [0, 1).
  shuffle(random = Math.random) {
    for (let i = this.cards.length - 1; i > this.dealIndex; i--) {
      const j = this.dealIndex + Math.floor(random() * (i - this.dealIndex + 1));
      [this.cards[i], this.cards[j]] = [this.cards[j], this.cards[i]];
    }
  }
  static blackjack() {
    return new Deck(Object.values(Suit).flatMap(suit =>
      Array.from({ length: 13 }, (_, i) => new BlackjackCard(i + 1, suit))));
  }
}

