const Rank = Object.freeze({ OPERATOR: 0, SUPERVISOR: 1, DIRECTOR: 2 });
class Call {
  constructor(id, requiredRank = Rank.OPERATOR) {
    if (![0, 1, 2].includes(requiredRank)) throw new RangeError("Invalid rank");
    this.id = id;
    this.requiredRank = requiredRank;
    this.state = "new";
    this.employee = null;
  }
}
class Employee {
  constructor(id, rank) {
    if (![0, 1, 2].includes(rank)) throw new RangeError("Invalid rank");
    this.id = id; this.rank = rank; this.call = null;
  }
}
class CallCenter {
  constructor(employees) {
    this.employees = [...employees].sort((a, b) => a.rank - b.rank);
    this.queue = [];
  }
  dispatch(call) {
    if (call.state !== "new") throw new Error("Call already dispatched");
    call.state = "queued";
    this.queue.push(call);
    this.drain();
  }
  drain() {
    const waiting = [];
    for (const call of this.queue) {
      const employee = this.employees.find(e => !e.call && e.rank >= call.requiredRank);
      if (!employee) { waiting.push(call); continue; }
      employee.call = call;
      call.employee = employee;
      call.state = "in_progress";
    }
    this.queue = waiting;
  }
  release(employee) {
    if (!this.employees.includes(employee) || !employee.call) throw new Error("No active call");
    const call = employee.call;
    employee.call = null; call.employee = null;
    return call;
  }
  complete(employee) {
    const call = this.release(employee);
    call.state = "complete";
    this.drain();
  }
  escalate(employee) {
    if (employee.rank === Rank.DIRECTOR) throw new Error("Director must resolve the call");
    const call = this.release(employee);
    call.requiredRank = employee.rank + 1;
    call.state = "queued";
    this.queue.push(call);
    this.drain();
  }
}

