class HashMap {
  constructor(capacity = 16) {
    if (!Number.isInteger(capacity) || capacity < 1) throw new RangeError("Invalid capacity");
    this.buckets = Array.from({ length: capacity }, () => []);
    this.size = 0;
  }
  bucket(key) {
    if (!Number.isSafeInteger(key)) throw new TypeError("Key must be a safe integer");
    const index = ((key % this.buckets.length) + this.buckets.length) % this.buckets.length;
    return this.buckets[index];
  }
  set(key, value) {
    const bucket = this.bucket(key);
    const entry = bucket.find(entry => entry.key === key);
    if (entry) entry.value = value;
    else { bucket.push({ key, value }); this.size++; }
    return this;
  }
  get(key) {
    const entry = this.bucket(key).find(entry => entry.key === key);
    if (!entry) throw new Error("Key not found");
    return entry.value;
  }
  has(key) { return this.bucket(key).some(entry => entry.key === key); }
  remove(key) {
    const bucket = this.bucket(key);
    const index = bucket.findIndex(entry => entry.key === key);
    if (index < 0) throw new Error("Key not found");
    bucket.splice(index, 1); this.size--;
  }
}

