class LRUCache {
  constructor(capacity) {
    if (!Number.isInteger(capacity) || capacity < 0) throw new RangeError("Invalid capacity");
    this.capacity = capacity;
    this.nodes = new Map();
    this.head = { next: null, prev: null };
    this.tail = { next: null, prev: this.head };
    this.head.next = this.tail;
  }
  unlink(node) {
    node.prev.next = node.next;
    node.next.prev = node.prev;
  }
  putFirst(node) {
    node.prev = this.head; node.next = this.head.next;
    this.head.next.prev = node; this.head.next = node;
  }
  has(key) { return this.nodes.has(key); }
  get(key) {
    const node = this.nodes.get(key);
    if (!node) return undefined;
    this.unlink(node); this.putFirst(node);
    return node.value;
  }
  set(key, value) {
    if (this.capacity === 0) return;
    let node = this.nodes.get(key);
    if (node) {
      node.value = value; this.unlink(node); this.putFirst(node);
      return;
    }
    if (this.nodes.size === this.capacity) {
      const oldest = this.tail.prev;
      this.unlink(oldest); this.nodes.delete(oldest.key);
    }
    node = { key, value, prev: null, next: null };
    this.nodes.set(key, node); this.putFirst(node);
  }
}

