class User {
  constructor(id, name) {
    this.id = id; this.name = name;
    this.friends = new Set();
    this.requests = new Map(); // requester ID -> pending / accepted / rejected
  }
}
class Chat {
  constructor(id, kind, ownerId, members) {
    this.id = id; this.kind = kind; this.ownerId = ownerId;
    this.members = new Set(members); this.messages = [];
  }
}
class ChatService {
  constructor() { this.users = new Map(); this.chats = new Map(); this.nextMessageId = 1; }
  user(id) {
    if (!this.users.has(id)) throw new Error("Unknown user");
    return this.users.get(id);
  }
  chat(id) {
    if (!this.chats.has(id)) throw new Error("Unknown chat");
    return this.chats.get(id);
  }
  addUser(id, name) {
    if (this.users.has(id)) throw new Error("User already exists");
    this.users.set(id, new User(id, name));
  }
  updateUser(id, name) { this.user(id).name = name; }
  removeUser(id) {
    this.user(id); this.users.delete(id);
    for (const user of this.users.values()) {
      user.friends.delete(id); user.requests.delete(id);
    }
    for (const [chatId, chat] of this.chats) {
      chat.members.delete(id);
      if (!chat.members.size || (chat.kind === "private" && chat.members.size < 2)) this.chats.delete(chatId);
      else if (chat.ownerId === id) chat.ownerId = chat.members.values().next().value;
    }
  }
  requestFriend(fromId, toId) {
    const from = this.user(fromId), to = this.user(toId);
    if (fromId === toId || from.friends.has(toId)) throw new Error("Invalid friend request");
    if (to.requests.get(fromId) === "pending") throw new Error("Request already pending");
    to.requests.set(fromId, "pending");
  }
  respondToRequest(toId, fromId, accept) {
    const to = this.user(toId), from = this.user(fromId);
    if (to.requests.get(fromId) !== "pending") throw new Error("No pending request");
    to.requests.set(fromId, accept ? "accepted" : "rejected");
    if (accept) {
      to.friends.add(fromId); from.friends.add(toId);
      if (from.requests.get(toId) === "pending") from.requests.set(toId, "accepted");
    }
  }
  removeFriend(firstId, secondId) {
    this.user(firstId).friends.delete(secondId);
    this.user(secondId).friends.delete(firstId);
  }
  requireFriends(firstId, secondId) {
    if (!this.user(firstId).friends.has(secondId)) throw new Error("Users must be friends");
    this.user(secondId);
  }
  createChat(id, ownerId, memberIds, kind = "group") {
    if (this.chats.has(id)) throw new Error("Chat already exists");
    if (!["group", "private"].includes(kind)) throw new Error("Invalid chat kind");
    this.user(ownerId);
    const members = new Set([ownerId, ...memberIds]);
    if (kind === "private" && members.size !== 2) throw new Error("Private chat needs two users");
    for (const member of members) if (member !== ownerId) this.requireFriends(ownerId, member);
    this.chats.set(id, new Chat(id, kind, ownerId, members));
  }
  invite(chatId, actorId, friendId) {
    const chat = this.chat(chatId);
    if (chat.kind !== "group" || !chat.members.has(actorId)) throw new Error("Cannot invite");
    this.requireFriends(actorId, friendId); chat.members.add(friendId);
  }
  removeMember(chatId, actorId, memberId) {
    const chat = this.chat(chatId);
    if (chat.kind !== "group" || (actorId !== memberId && actorId !== chat.ownerId)) throw new Error("Not permitted");
    if (!chat.members.has(actorId)) throw new Error("Not a member");
    chat.members.delete(memberId);
    if (!chat.members.size) this.chats.delete(chatId);
    else if (chat.ownerId === memberId) chat.ownerId = chat.members.values().next().value;
  }
  send(chatId, senderId, text) {
    const chat = this.chat(chatId); this.user(senderId);
    if (!chat.members.has(senderId)) throw new Error("Not a member");
    if (chat.kind === "private") {
      const friendId = [...chat.members].find(id => id !== senderId);
      this.requireFriends(senderId, friendId);
    }
    if (typeof text !== "string" || !text.trim()) throw new Error("Message is empty");
    const message = { id: this.nextMessageId++, senderId, text, timestamp: Date.now() };
    chat.messages.push(message);
    return message;
  }
}

