const Size = Object.freeze({ MOTORCYCLE: 0, COMPACT: 1, LARGE: 2 });
class Vehicle {
  constructor(plate, minimumSize, spotsNeeded) {
    this.plate = plate; this.minimumSize = minimumSize;
    this.spotsNeeded = spotsNeeded; this.spots = [];
  }
  fits(spot) { return spot.size >= this.minimumSize; }
  leave() {
    for (const spot of this.spots) spot.vehicle = null;
    this.spots = [];
  }
}
class Motorcycle extends Vehicle { constructor(plate) { super(plate, Size.MOTORCYCLE, 1); } }
class Car extends Vehicle { constructor(plate) { super(plate, Size.COMPACT, 1); } }
class Bus extends Vehicle { constructor(plate) { super(plate, Size.LARGE, 5); } }
class ParkingSpot {
  constructor(row, number, size) {
    this.row = row; this.number = number; this.size = size; this.vehicle = null;
  }
  canFit(vehicle) { return this.vehicle === null && vehicle.fits(this); }
}
class Level {
  constructor(id, rows) {
    this.id = id;
    this.spots = rows.flatMap((sizes, row) =>
      sizes.map((size, number) => new ParkingSpot(row, number, size)));
  }
  get available() { return this.spots.filter(s => s.vehicle === null).length; }
  park(vehicle) {
    if (vehicle.spots.length) throw new Error("Vehicle already parked");
    let run = [];
    for (const spot of this.spots) {
      const previous = run[run.length - 1];
      if (!spot.canFit(vehicle)) { run = []; continue; }
      if (previous && (previous.row !== spot.row || previous.number + 1 !== spot.number)) run = [];
      run.push(spot);
      if (run.length === vehicle.spotsNeeded) {
        for (const reserved of run) reserved.vehicle = vehicle;
        vehicle.spots = run;
        return true;
      }
    }
    return false;
  }
}
class ParkingLot {
  constructor(levels) { this.levels = [...levels]; }
  park(vehicle) {
    if (vehicle.spots.length) throw new Error("Vehicle already parked");
    return this.levels.some(level => level.park(vehicle));
  }
}

